from six.moves import queue
from ta_tshark_json_parser.tshark_source import TsharkSource
from ta_pcmd.logger_config import configure_logger

PROTOCOL = {'4G': 'nsetap',
            '5G': 'nsetapx'}

TSHARK_INTERFACE = 'eth3'
TSHARK_COMMAND = "tshark -o ntrstr.defragment:TRUE -o ntrstr.port:{port} " \
                 "-i {interface} -Y '{protocol}' -T json " \
                 "-f 'tcp dst port {port} and dst host {dst_host}' -l"


class JsonTsharkPCMDSource(TsharkSource):
    def __init__(self, ip, port, callback=None, technology='4G', tshark_interface=TSHARK_INTERFACE):
        self.ip = ip
        self.port = port
        self.non_subclassed_logger = configure_logger('ta_pcmd.json_tshark_source_{}_{}'.format(self.ip, self.port))
        self.tshark_interface = tshark_interface
        self.queue = queue.Queue()
        self.callback = callback
        self.protocol = PROTOCOL[technology]
        super(JsonTsharkPCMDSource, self).__init__(queue=self.queue, layer=self.protocol)
        self.non_subclassed_logger.debug('Tshark started for protocol: {}'.format(self.protocol))

    def get_unique_logger_name(self):
        return '{}_{}'.format(self.ip, self.port)

    def get_tshark_command(self):
        ''' to be added '''

        tshark_cmd = TSHARK_COMMAND.format(protocol=self.protocol, port=self.port, interface=self.tshark_interface,
                                           dst_host=self.ip)
        self.non_subclassed_logger.debug('Starting tshark with command:\n{}'.format(tshark_cmd))
        return tshark_cmd

    def process_data_record(self, data_record):
        ''' to be added '''
        if self.callback:
            protocols = data_record['_source']['layers']
            for protocol_name in sorted(protocols.keys()):
                if self.protocol in protocol_name:
                    record = protocols[protocol_name]
                    self.callback(record)
        return data_record

    def get_opened_connection(self):
        ''' to be added '''
        return self.get_opened_connection_local()
